export function renderBookOverview(project, chapters) {
  const total = Object.values(chapters).reduce((sum, chapter) => sum + chapter.words, 0);
  return `<section class="book-overview-view"><header><div><span>书籍工作区</span><h1>${project.bookTitle}</h1><p>${project.description}</p></div><button data-action="edit-book-profile">编辑资料</button></header><nav class="overview-tabs"><button class="active" data-action="overview-profile">书籍概览</button><button data-action="overview-pages">页面总览</button></nav><div class="overview-content"><section class="book-profile-card"><div class="book-cover"><span>STORYOS ORIGINAL</span><strong>${project.bookTitle}</strong><small>长篇小说</small></div><div class="profile-copy"><span class="page-eyebrow">创作概览</span><h2>${project.bookTitle}</h2><p>${project.description}</p><div class="stat-grid"><span><b>2</b><small>分卷</small></span><span><b>${Object.keys(chapters).length}</b><small>章节</small></span><span><b>${total.toLocaleString("zh-CN")}</b><small>字数</small></span></div><div class="progress-block"><span><b>本周进度</b><small>目标 8,000 字</small></span><div><i style="width:68%"></i></div><small>已完成 5,420 字 · 保持这个节奏</small></div></div></section></div></section>`;
}

export function renderPageOverview(chapters) {
  return `<section class="book-overview-view"><header><div><span>整书浏览</span><h1>页面总览</h1><p>按章节快速浏览当前书稿的页面与写作状态。</p></div><button data-action="add-chapter">＋ 新建章节</button></header><nav class="overview-tabs"><button data-action="overview-profile">书籍概览</button><button class="active" data-action="overview-pages">页面总览</button></nav><div class="page-grid">${Object.entries(chapters).map(([id, chapter]) => `<button class="page-card" data-chapter="${id}"><span>${chapter.volume} · 第 ${chapter.number} 章</span><h3>${chapter.title}</h3><p>${chapter.content.slice(0, 2).join(" ")}</p><footer><span>${chapter.status}</span><b>${chapter.words.toLocaleString("zh-CN")} 字</b></footer></button>`).join("")}<button class="page-card add-page" data-action="add-chapter"><b>＋</b><span>新建章节</span></button></div></section>`;
}
